class Solution {
public:
    int countWays(std::vector<std::vector<int>>& ranges) {
        std::sort(ranges.begin(), ranges.end());
        long long MOD = 1e9 + 7;
        int components = 0;
        int max_end = -1;
        for (const auto& r : ranges) {
            if (r[0] > max_end) {
                components++;
            }
            max_end = std::max(max_end, r[1]);
        }
        long long ans = 1;
        for (int i = 0; i < components; ++i) {
            ans = (ans * 2) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int countWays(int[][] ranges) {
        java.util.Arrays.sort(ranges, (a, b) -> Integer.compare(a[0], b[0]));
        long MOD = 1_000_000_007L;
        int components = 0;
        int maxEnd = -1;
        for (int[] r : ranges) {
            if (r[0] > maxEnd) {
                components++;
            }
            maxEnd = Math.max(maxEnd, r[1]);
        }
        long ans = 1;
        for (int i = 0; i < components; i++) {
            ans = (ans * 2) % MOD;
        }
        return (int) ans;
    }
}

var countWays = function(ranges) {
    ranges.sort((a, b) => a[0] - b[0]);
    const MOD = 1000000007n;
    let components = 0;
    let maxEnd = -1;
    for (const [start, end] of ranges) {
        if (start > maxEnd) {
            components++;
        }
        maxEnd = Math.max(maxEnd, end);
    }
    let ans = 1n;
    for (let i = 0; i < components; i++) {
        ans = (ans * 2n) % MOD;
    }
    return Number(ans);
};
